const ACCOUNT_KEY='shatter-local-accounts-v1',SESSION_KEY='shatter-local-session-v1',ITERATIONS=180000;
function accounts(){try{const raw=JSON.parse(localStorage.getItem(ACCOUNT_KEY)||'[]');return Array.isArray(raw)?raw.filter(u=>u&&typeof u.id==='string'&&/^[a-f0-9-]{36}$/.test(u.id)&&typeof u.name==='string'&&typeof u.salt==='string'&&/^[a-f0-9]{32}$/.test(u.salt)&&typeof u.hash==='string'&&/^[a-f0-9]{64}$/.test(u.hash)):[];}catch{return [];}}
const hex=bytes=>Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');
async function passwordHash(password,salt){if(!globalThis.crypto?.subtle)throw Error('当前浏览器不支持本机账号，请使用新版 Edge 或 Chrome。');const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']),bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:Uint8Array.from(salt.match(/../g),n=>parseInt(n,16)),iterations:ITERATIONS,hash:'SHA-256'},key,256);return hex(new Uint8Array(bits));}
export function currentUser(){try{const id=sessionStorage.getItem(SESSION_KEY),u=accounts().find(u=>u.id===id);return u?{id:u.id,name:u.name}:null;}catch{return null;}}
export function logoutAccount(){sessionStorage.removeItem(SESSION_KEY);}
export async function registerAccount(name,password){name=String(name).trim();if(!/^[\p{L}\p{N}_-]{2,18}$/u.test(name))throw Error('用户名需为 2–18 个汉字、字母、数字、下划线或短横线。');if(typeof password!=='string'||password.length<6||password.length>128)throw Error('密码需为 6–128 个字符。');if(accounts().some(u=>u.name.toLowerCase()===name.toLowerCase()))throw Error('这个本机用户名已经注册。');const salt=hex(crypto.getRandomValues(new Uint8Array(16))),hash=await passwordHash(password,salt),user={id:crypto.randomUUID(),name,salt,hash};const list=accounts();if(list.some(u=>u.name.toLowerCase()===name.toLowerCase()))throw Error('这个本机用户名已经注册。');localStorage.setItem(ACCOUNT_KEY,JSON.stringify([...list,user]));sessionStorage.setItem(SESSION_KEY,user.id);return {id:user.id,name};}
export async function loginAccount(name,password){name=String(name).trim();const user=accounts().find(u=>u.name.toLowerCase()===name.toLowerCase());if(!user||await passwordHash(String(password),user.salt)!==user.hash)throw Error('用户名或密码不正确。');sessionStorage.setItem(SESSION_KEY,user.id);return {id:user.id,name:user.name};}
